import React from 'react';
import { Navbar, Nav, Container } from 'react-bootstrap';
import { Link } from 'react-router-dom';

const Navigation = () => {
  return (
    <Navbar bg="dark" variant="dark" expand="lg">
      <Container>
        <Navbar.Brand as={Link} to="/">Portfolio Evaluator</Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link as={Link} to="/">Dashboard</Nav.Link>
            <Nav.Link as={Link} to="/portfolios">Portfolios</Nav.Link>
            <Nav.Link as={Link} to="/import">Import Data</Nav.Link>
            <Nav.Link as={Link} to="/performance">Performance</Nav.Link>
            <Nav.Link as={Link} to="/tax">Tax Analysis</Nav.Link>
            <Nav.Link as={Link} to="/cashflow">Cash Flow</Nav.Link>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default Navigation;
